import 'dart:developer' as developer;
import 'package:flutter/foundation.dart';
import 'package:firebase_core/firebase_core.dart';
import '../../firebase_options.dart';

/// Firebase initialization service abstraction.
/// Initializes Firebase with platform-specific options generated by FlutterFire CLI.
class FirebaseService {
  FirebaseService._();

  static bool _isInitialized = false;
  static bool get isInitialized => _isInitialized;

  static Future<void> initialize() async {
    try {
      if (Firebase.apps.isEmpty) {
        // Initialize Firebase with the FlutterFire-generated options
        await Firebase.initializeApp(
          options: DefaultFirebaseOptions.currentPlatform,
        );
      }
      _isInitialized = true;
      developer.log('Firebase initialized successfully', name: 'FirebaseService');
    } catch (e, stack) {
      if (Firebase.apps.isNotEmpty) {
        _isInitialized = true;
      }
      if (kDebugMode) {
        developer.log(
          'Firebase initialization error: $e',
          name: 'FirebaseService',
          error: e,
          stackTrace: stack,
        );
      }
    }
  }
}

